package server

import (
	"context"
	"encoding/json"
	"net/http"
	"strings"
	"time"
)

// Time Travel — 과거 어느 날의 우주를 다시 세운다.
//
// 이력 테이블이 필요할 것 같지만 그렇지 않다. 친밀도와 흐름은 저장된 사실이
// 아니라 교류에서 계산해 낸 값이고, 교류에는 일어난 시각이 남아 있다. 그래서
// 계산의 기준 시각만 과거로 옮기면 그날의 상태가 그대로 나온다.
//
// 다만 정직하게 말해 둘 것이 있다. 중요도·소속·고정 여부는 사용자가 직접
// 정하는 값이라 변경 이력이 없다. 그 세 가지는 오늘의 값을 쓴다. 되살아나는
// 것은 "교류가 만든 거리와 흐름"이다.

// parseOrbitAt은 ?at= 값을 읽는다. 없으면 현재 시점을 뜻한다.
func parseOrbitAt(raw string) (time.Time, bool, error) {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return time.Time{}, false, nil
	}
	for _, layout := range []string{time.RFC3339, "2006-01-02"} {
		if at, err := time.Parse(layout, raw); err == nil {
			return at, true, nil
		}
	}
	return time.Time{}, false, errInvalidOrbitAt
}

type orbitAtError struct{}

func (orbitAtError) Error() string { return "날짜 형식을 확인해 주세요 (예: 2025-06-01)" }

var errInvalidOrbitAt = orbitAtError{}

// historicalNode는 과거 시점 계산에 필요한 사람 정보다.
type historicalNode struct {
	ID          string
	Name        string
	Avatar      string
	Importance  float64
	StableX     float64
	StableY     float64
	Categories  []string
	Label       string
	Anchored    bool
	MemoryCount int
}

// orbitAt은 주어진 시각 기준으로 노드를 다시 계산한다.
func (s *Server) orbitAt(ctx context.Context, userID string, at time.Time) ([]map[string]any, map[string]int, error) {
	// 그날 내 우주에 있었던 사람만 세운다.
	//
	// 판정 기준을 people.created_at으로만 두면 안 된다. 그건 관계가 시작된
	// 시점이 아니라 Orbit에 적어 넣은 시점이라, 오늘 등록하며 과거 교류를
	// 함께 기록한 사람이 통째로 사라진다. 그날 이전의 교류나 첫 만남 기록이
	// 있으면 그때 이미 곁에 있던 사람으로 본다.
	rows, err := s.store.DB.Query(ctx, `SELECT p.id,p.display_name,p.avatar_url,r.importance,r.stable_x,r.stable_y,r.categories,r.relationship_label,r.anchored,(SELECT count(*) FROM memories m WHERE m.user_id=p.user_id AND m.person_id=p.id AND m.status='approved' AND coalesce(m.occurred_at,m.created_at)<=$2) FROM people p JOIN relationships r ON r.person_id=p.id WHERE p.user_id=$1 AND (p.created_at<=$2 OR (p.first_met IS NOT NULL AND p.first_met<=$2::date) OR EXISTS (SELECT 1 FROM interactions i WHERE i.user_id=p.user_id AND i.person_id=p.id AND i.occurred_at<=$2)) ORDER BY r.importance DESC LIMIT 1000`, userID, at)
	if err != nil {
		return nil, nil, err
	}
	defer rows.Close()
	people := []historicalNode{}
	contexts := map[string]int{}
	for rows.Next() {
		var n historicalNode
		var raw []byte
		if err := rows.Scan(&n.ID, &n.Name, &n.Avatar, &n.Importance, &n.StableX, &n.StableY, &raw, &n.Label, &n.Anchored, &n.MemoryCount); err != nil {
			return nil, nil, err
		}
		_ = json.Unmarshal(raw, &n.Categories)
		if n.Categories == nil {
			n.Categories = []string{}
		}
		for _, c := range n.Categories {
			contexts[c]++
		}
		people = append(people, n)
	}
	if err := rows.Err(); err != nil {
		return nil, nil, err
	}

	// 그 시점의 지표를 내려면 그때까지의 교류만 본다. 사람마다 따로 묻지 않고
	// 한 번에 받아 묶는다.
	points := map[string][]interactionPoint{}
	last := map[string]time.Time{}
	interactionRows, err := s.store.DB.Query(ctx, `SELECT person_id,occurred_at,weight FROM interactions WHERE user_id=$1 AND occurred_at<=$2`, userID, at)
	if err != nil {
		return nil, nil, err
	}
	defer interactionRows.Close()
	window := at.AddDate(-1, 0, 0)
	for interactionRows.Next() {
		var personID string
		var p interactionPoint
		if err := interactionRows.Scan(&personID, &p.At, &p.Weight); err != nil {
			return nil, nil, err
		}
		// 마지막 접촉은 창을 두지 않는다. 점수만 1년치를 본다.
		if known, ok := last[personID]; !ok || p.At.After(known) {
			last[personID] = p.At
		}
		if p.At.After(window) {
			points[personID] = append(points[personID], p)
		}
	}
	if err := interactionRows.Err(); err != nil {
		return nil, nil, err
	}

	nodes := make([]map[string]any, 0, len(people))
	for _, n := range people {
		_, closeness, momentum := relationshipMetrics(points[n.ID], at)
		node := map[string]any{
			"id": n.ID, "name": n.Name, "avatar_url": n.Avatar,
			"importance": n.Importance, "closeness": closeness, "momentum": momentum,
			"x": n.StableX, "y": n.StableY, "categories": n.Categories,
			"label": n.Label, "anchored": n.Anchored, "memory_count": n.MemoryCount,
		}
		if when, ok := last[n.ID]; ok {
			node["last_interaction_at"] = when
		} else {
			node["last_interaction_at"] = nil
		}
		nodes = append(nodes, node)
	}
	return nodes, contexts, nil
}

// orbitRange는 시간 여행이 가능한 구간을 알려준다.
// 시작점은 첫 기록이고, 그 이전에는 보여 줄 우주가 없다.
//
// 두 테이블을 따로 훑는다 — 조인하면 사람×교류 곱이 된다. 사람이 한 명도
// 없으면 교류도 없으므로(interactions.person_id 가 people 을 참조) NULL 이다.
func (s *Server) orbitRange(ctx context.Context, userID string) (*time.Time, error) {
	var first *time.Time
	err := s.store.DB.QueryRow(ctx, `SELECT least((SELECT min(created_at) FROM people WHERE user_id=$1),(SELECT min(occurred_at) FROM interactions WHERE user_id=$1))`, userID).Scan(&first)
	return first, err
}

func (s *Server) writeOrbitAt(w http.ResponseWriter, r *http.Request, at time.Time) {
	u := userFromContext(r.Context())
	nodes, contexts, err := s.orbitAt(r.Context(), u.ID, at)
	if err != nil {
		internalError(w, r, err)
		return
	}
	links, err := s.orbitLinks(r.Context(), u.ID)
	if err != nil {
		internalError(w, r, err)
		return
	}
	categories, err := s.userCategories(r.Context(), u.ID)
	if err != nil {
		internalError(w, r, err)
		return
	}
	writeJSON(w, 200, map[string]any{
		"center":     map[string]string{"id": u.ID, "name": u.DisplayName},
		"nodes":      nodes,
		"contexts":   contexts,
		"links":      links,
		"categories": categories,
		"at":         at,
		// 과거 화면임을 화면이 분명히 알 수 있게 표시한다.
		"historical":   true,
		"generated_at": time.Now(),
	})
}
package server

import (
	"context"
	"os"
	"testing"
	"time"

	"github.com/hkjang/orbit/internal/id"
	"github.com/hkjang/orbit/internal/store"
)

// 실제 postgres 를 끼는 테스트. ORBIT_TEST_DATABASE_URL 이 비어 있으면 건너뛴다.
//
//	docker run -d --name orbit-pg -e POSTGRES_PASSWORD=orbit -e POSTGRES_DB=orbit -p 127.0.0.1:55470:5432 postgres:16-alpine
//	ORBIT_TEST_DATABASE_URL='postgres://postgres:orbit@127.0.0.1:55470/orbit?sslmode=disable' go test -run TestOrbitRange -v ./internal/server/
//
// 마이그레이션은 store.Open 이 그대로 적용한다. 데이터는 시험마다 새 사용자
// 아래에만 넣고 끝나면 사용자 행을 지워(FK 가 ON DELETE CASCADE) 흔적을 남기지 않는다.
func openTestStore(t *testing.T) *store.Store {
	t.Helper()
	dsn := os.Getenv("ORBIT_TEST_DATABASE_URL")
	if dsn == "" {
		t.Skip("ORBIT_TEST_DATABASE_URL 이 비어 있어 DB 테스트를 건너뛴다")
	}
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	st, err := store.Open(ctx, dsn, nil)
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(st.Close)
	return st
}

// seedUser 는 사용자 행을 직접 넣는다. Bootstrap 은 관리자 계정과 설정 행을
// 함께 만들어 부작용이 있으므로 쓰지 않는다.
func seedUser(t *testing.T, st *store.Store) string {
	t.Helper()
	userID := id.New()
	if _, err := st.DB.Exec(context.Background(), `INSERT INTO users (id,username,display_name) VALUES ($1,$2,$3)`, userID, "t-"+userID[:8], "시험 사용자"); err != nil {
		t.Fatalf("seed user: %v", err)
	}
	t.Cleanup(func() {
		_, _ = st.DB.Exec(context.Background(), `DELETE FROM users WHERE id=$1`, userID)
	})
	return userID
}

func seedPerson(t *testing.T, st *store.Store, userID string, createdAt time.Time) string {
	t.Helper()
	personID := id.New()
	if _, err := st.DB.Exec(context.Background(), `INSERT INTO people (id,user_id,display_name,key_version,created_at) VALUES ($1,$2,$3,1,$4)`, personID, userID, "시험 인물", createdAt); err != nil {
		t.Fatalf("seed person: %v", err)
	}
	return personID
}

func seedInteraction(t *testing.T, st *store.Store, userID, personID string, occurredAt time.Time) {
	t.Helper()
	if _, err := st.DB.Exec(context.Background(), `INSERT INTO interactions (id,user_id,person_id,kind,occurred_at,key_version) VALUES ($1,$2,$3,'note',$4,1)`, id.New(), userID, personID, occurredAt); err != nil {
		t.Fatalf("seed interaction: %v", err)
	}
}

// legacyOrbitRange 는 예전 질의(사람 LEFT JOIN 교류 — 사람×교류 곱을 만든다)를
// 회귀 기준으로 그대로 돌린다. 새 질의는 값이 같아야 한다.
func legacyOrbitRange(t *testing.T, st *store.Store, userID string) *time.Time {
	t.Helper()
	var first *time.Time
	if err := st.DB.QueryRow(context.Background(), `SELECT least(min(p.created_at),min(i.occurred_at)) FROM people p LEFT JOIN interactions i ON i.user_id=p.user_id WHERE p.user_id=$1`, userID).Scan(&first); err != nil {
		t.Fatalf("legacy orbitRange: %v", err)
	}
	return first
}

func sameInstant(a, b *time.Time) bool {
	if a == nil || b == nil {
		return a == nil && b == nil
	}
	return a.Equal(*b)
}

func TestOrbitRangeMatchesLegacyJoin(t *testing.T) {
	st := openTestStore(t)
	s := &Server{store: st}
	ctx := context.Background()
	base := time.Date(2024, 3, 1, 12, 0, 0, 0, time.UTC)

	// 다른 사용자의 더 오래된 사람·교류를 먼저 깔아 둔다. 아래 모든 경우에서
	// 내 값에 섞여 들면 안 된다.
	other := seedUser(t, st)
	otherPerson := seedPerson(t, st, other, base.AddDate(-5, 0, 0))
	seedInteraction(t, st, other, otherPerson, base.AddDate(-6, 0, 0))

	check := func(t *testing.T, userID string, want *time.Time) {
		t.Helper()
		got, err := s.orbitRange(ctx, userID)
		if err != nil {
			t.Fatalf("orbitRange: %v", err)
		}
		if !sameInstant(got, want) {
			t.Fatalf("orbitRange = %v, want %v", got, want)
		}
		if legacy := legacyOrbitRange(t, st, userID); !sameInstant(got, legacy) {
			t.Fatalf("orbitRange = %v, 옛 질의는 %v", got, legacy)
		}
	}

	t.Run("사람이 없으면 nil", func(t *testing.T) {
		me := seedUser(t, st)
		check(t, me, nil)
	})

	t.Run("사람만 있으면 created_at", func(t *testing.T) {
		me := seedUser(t, st)
		seedPerson(t, st, me, base)
		seedPerson(t, st, me, base.AddDate(0, 1, 0))
		check(t, me, &base)
	})

	t.Run("더 앞선 교류가 있으면 occurred_at", func(t *testing.T) {
		me := seedUser(t, st)
		p := seedPerson(t, st, me, base)
		earlier := base.AddDate(-1, 0, 0)
		seedInteraction(t, st, me, p, earlier)
		seedInteraction(t, st, me, p, base.AddDate(0, 0, 1))
		check(t, me, &earlier)
	})

	t.Run("다른 사용자 것은 보지 않는다", func(t *testing.T) {
		me := seedUser(t, st)
		p := seedPerson(t, st, me, base)
		seedInteraction(t, st, me, p, base.AddDate(0, 0, 3))
		// 다른 사용자의 5~6년 전 기록이 있어도 내 첫 기록은 base 다.
		check(t, me, &base)
	})
}
# Orbit architecture

Orbit is a modular Go monolith with an embedded React application. A single
service image serves the REST API, MCP endpoint, OIDC flow, AI stream proxy and
static UI. PostgreSQL is the only runtime dependency.

## Runtime boundaries

```text
Browser / MCP client
        │
        ▼
Orbit :8080
 ├─ local session + dynamic Keycloak OIDC
 ├─ relationship / memory domain
 ├─ user key vault + API key scopes
 ├─ approval workflow (optional)
 ├─ OpenAI Responses-compatible SSE gateway
 ├─ REST / OpenAPI
 └─ Streamable HTTP MCP
        │
        ▼
PostgreSQL
```

All mutable service settings live in the `settings` table. Client secrets and
AI API keys are encrypted with the master encryption key. Contact fields,
interaction summaries and memory content are encrypted using versioned,
per-user data encryption keys. User keys are wrapped by the master key.

Local password login is throttled in memory: ten failures for the same
username from the same client address within 15 minutes lock that pair for
15 minutes (`429 too_many_attempts` with `Retry-After`). The key combines
username and address so a stranger cannot lock a real account by guessing its
name, and neighbours behind one proxy do not lock each other. The moment a lock
starts is written to the audit log as `auth.login_blocked`.

Key rotation is transactional: Orbit creates a new data key, re-encrypts all
current protected fields and retires the old key in one database transaction.

## Tests

`go test ./...` runs without a database. Tests that need real SQL (for
example `internal/server/timetravel_db_test.go`) skip unless
`ORBIT_TEST_DATABASE_URL` points at a PostgreSQL the test may migrate and
write to; the file header shows a one-line `docker run` that provides one.

## Relationship visual grammar

- Planet size: long-term importance
- Distance: current interaction-derived closeness
- Brightness: current activity
- Green arc: positive momentum
- Stable angle: deterministic spatial memory
- Context color: overlapping relationship context

Numbers are internal signals and are translated to humane phrases in the UI.

# aidev 의 에이전트들 — 서로를 보완하는 구조

> 2026-09-19 부터 이 역할들은 회사 조직(headcount 부서)에 배속돼 부서 스킬을 싣고 돈다. 조직도·권한·차단 소견·이사회는 **[COMPANY.md](COMPANY.md)** 에.

한 세션이 파악·선택·구현·검증·기록을 다 하던 구조를, 역할이 다른 여러 세션이 서로의
산출물을 검사하는 구조로 바꿨다 (2026-09-18). 원칙은 셋이다.

1. **만드는 자와 검사하는 자를 분리한다.** 구현자는 자기 코드를 승인하지 못한다. 비평가는 코드를 고치지 못한다.
2. **읽기만 하는 자가 방향을 정한다.** 정찰은 커밋할 수 없으므로 "고치기 쉬운 것" 이 아니라 "고칠 가치가 있는 것" 을 고른다.
3. **배우는 자가 모두에게 되먹인다.** 거절·회귀·반려는 원장에 묻히지 않고 규칙이 되어 다음 정찰·구현·비평이 먼저 읽는다.

명부는 `agents/registry.json`, 예산은 `state/default.policy.json` 의 `budget_usd`, 역할별 켜고 끄기는 정책의 `agents` 다.

## 한 회차 (bin/run.sh round_body)

```
정찰(scout) ──brief.md──▶ 구현(builder) ──commits──▶ 러너 검증(verify/secrets/artifacts)
    ▲ ideas.json                                            │ 통과
    │                                                        ▼
    │                      ┌──── 거절(reasons) ────  비평(critic) ── 승인 ──▶ PR ──▶ CI ──▶ 머지 ──▶ 릴리즈(releaser)
    │                      ▼                             ▲
    │                 수리(repairer) ──commit──▶ 재검증 ──┘  (repair_max 번)
    │
  기록·학습(historian): campaign-lessons / operator-preferences ──▶ 정찰·구현·비평·PR 심사의 프롬프트에 주입
```

| 역할 | 파일 | 할 수 있는 것 | 만드는 것 | 누가 검사하나 |
|---|---|---|---|---|
| **정찰** scout | `agents/scout.md` | 읽기, 테스트 실행. **커밋 불가**(남긴 변경은 러너가 버림) | `brief.md`(과제·수용 기준·검증 명령·건드릴 파일·차선), `ideas.json` 재평가 | 구현자가 과제서의 근거를 코드로 확인. 맞지 않으면 차선을 고르고 원장에 이유 |
| **구현** builder | `prompt.md` | 편집·실행·커밋 | 커밋, `ledger-entry.md`, `ideas.json` | 러너 검증 → 비평가 |
| **비평** critic | `review-prompt.md` | 읽기·실행. **편집 불가** | `review.json`(verdict·reasons·risk) | `gate.py review` 가 형식 검사. 승인만 머지로 |
| **수리** repairer | `agents/repairer.md` | 편집·커밋(지적된 결함만) | 수리 커밋, `fix-summary.md` | 재검증 → 비평가가 다시 본다. 실패하면 러너가 수리 커밋을 버림 |
| **중재** arbiter | `agents/arbiter.md` | 읽기·실행. **편집 불가** | `arbiter.json`(verdict·사유별 확인/반증) | `gate.py review`. 승인이면 비평 승인과 같이 취급 |
| **릴리즈** releaser | `release-prompt.md` | 관례대로 버전·태그·자산 | `release.json`, 태그, 자산 | `gate.py release`, 자산 매니페스트, 워크플로 결과 |

- **프로젝트 프로필** `state/<프로젝트>.profile.md`: 정찰이 유지하는 저장소 요약(목적·스택·구조·검증 명령·관례·위험 구역·자주 깨지는 곳·검증 함정, 60줄 안). 없거나 14일이 지나면 정찰이 다시 쓰고, 비밀값 검사를 통과한 것만 저장된다. 구현·비평·수리·중재·PR 수리가 모두 이것부터 읽는다 — 매 회차 "파악" 에 쓰던 시간을 줄이고 모든 역할이 같은 그림을 본다.
- **중재**: 비평가가 거절했는데 수리 에이전트가 "지적이 틀렸다" 며 `fix-summary.md` 에 근거만 남기고 손대지 않았을 때만 돈다. 제3의 세션이 양쪽 주장을 읽고 코드로 확인해 판정한다. 읽기만으로 판단할 수 없는 사유는 비평가 편이다. 끄기: 정책 `agents.arbiter: false`.
- 정찰이 실패하거나 예산이 없으면 구현자가 예전처럼 직접 고른다(`stage scout failed|hold`).
- 비평·수리 루프는 **자동 머지할 변경**에만 돈다(자율화 low-risk 이상, 보호 파일 없음). 보호 파일을 건드린 변경은 사람 또는 PR 처리기가 본다.
- 수리가 `repair_max`(기본 1)번 안에 비평을 통과하지 못하면 PR 을 열고 `review held` 로 보류한다 — 그러면 PR 처리기가 한 시간 뒤 다시 잡는다.

